// Every pawn on the viewed layer, in one instanced draw.
//
// ONE CALL FOR THE WHOLE TABLE, for the tile pass's reason: the sprite cache is
// a texture array, so a draw can sample every picture on the table at once and
// the layer index rides in as a per-instance attribute. Five hundred pawns and
// five are the same number of draw calls.
//
// CREATURES ARE DISCS AND OBJECTS ARE RECTANGLES, and the difference is one
// float per instance rather than two passes. A creature is masked to a disc
// with a border in its kind's colour and its picture COVERS that disc -- cropped
// rather than letterboxed, because a portrait with bars down the side inside a
// circle looks like a mistake. An object is drawn unmasked with its picture
// CONTAINED in its quad, aspect kept, because the quad is the wagon's actual
// size on the floor and a wagon stretched to fill it is the wrong wagon.
//
// AN OBJECT'S QUAD IS THE PICTURE'S OWN PIXELS, so contain normally fits it
// exactly and the two factors come back at one. They stop being one when the GM
// has typed a different width or height into the pawn's dialog, which is the
// one case where an object is deliberately not the shape of its picture.
//
// AND AN OBJECT'S QUAD TURNS. The rotation is a per-instance pair of floats and
// the vertex shader spins the corner offset by it, which rotates the picture
// with the rectangle -- because the fragment shader's texture lookup is in the
// quad's own local space and never learns the angle at all. A creature's is
// always zero: a disc has no facing.
//
// A WOUNDED CREATURE IS DRAWN DIFFERENTLY RATHER THAN RINGED, and the whole of
// that happens in here. Blood soaks in from the rim of the disc and pools toward
// its bottom, the colour drains toward a cold grey, one of the nine splatters is
// composited over the portrait, and a glow on the inside of the rim beats.
// Nothing about it leaves the pawn's own circle: what is OUTSIDE a pawn is its
// conditions, and health is not one of those. See wounds.ts.
//
// THE PULSE PHASE IS A UNIFORM AND NOT AN ATTRIBUTE, which is the one thing that
// makes the above free. This buffer is rebuilt when the table changes; a
// per-instance animated value would rebuild every pawn on the table sixty times
// a second to move one ring. So the instance carries only how hurt the creature
// is and whether it beats -- both of which change when its hit points do, which
// is a rebuild already -- and the phase arrives per frame for all of them at
// once. Every dying creature therefore beats in step, which is a choice rather
// than a compromise: together reads as urgent, out of phase reads as noise.
//
// THE INSTANCE BUFFER IS REBUILT WHEN THE TABLE CHANGES AND NOT PER FRAME. A
// pan or a zoom changes the matrix and nothing else, which is the common case
// by a wide margin; what forces a rebuild is a pawn moving, appearing, changing
// floor or size, or a picture arriving -- the last because a picture's aspect
// ratio is what the quad is fitted to.

import type { Camera } from "./camera.ts";
import type { Grid, HPBand, Pawn } from "../protocol.ts";
import type { SpriteCache } from "./sprites.ts";
import { KIND_COLORS } from "./sprites.ts";
import { SKULL } from "./sprites.ts";
import {
	BEAT_NONE, BLOOD_DRIED, BLOOD_FRESH,
	beats, bleeds, bloodSprite, hurt, seed,
} from "./wounds.ts";
import { clipMatrix } from "./camera.ts";
import { createProgram, uniforms } from "./gl.ts";
import { pawnExtents, radians } from "./path.ts";
import { compareStack } from "./scene.ts";

// FLOATS_PER_INSTANCE: the rectangle, the border colour, the style, the fit and
// the angle's cosine and sine. Four vec4s and a vec2.
//
// THE ANGLE ARRIVES PRE-RESOLVED. A cosine and a sine per instance rather than
// a degree per instance, because the shader would otherwise compute the same
// two transcendentals for all four corners of every quad in every frame, and
// the buffer is rebuilt only when the table changes. The wound rides in beside
// it, in the two floats that pair makes spare.
const FLOATS_PER_INSTANCE = 20;

// BORDER_PIXELS is the ring round a creature, in DEVICE pixels rather than map
// pixels, so it is the same weight at every zoom. A border that scaled with the
// camera would be invisible zoomed out and a thick band zoomed in.
const BORDER_PIXELS = 2;

// HIDDEN_ALPHA is how a pawn players cannot see looks to the GM. Desaturated as
// well, so "hidden" is legible at a glance rather than a shade of the same
// thing -- a GM scanning a table has to be able to tell without hovering.
export const HIDDEN_ALPHA = 0.6;
const HIDDEN_GREY = 0.7;

// SKULL_SCALE is the dead-creature mark, as a fraction of the pawn's diameter.
const SKULL_SCALE = 0.7;

// SHAPE_DISC, SHAPE_RECT and SHAPE_STAIN are what an instance is. The first two
// are a creature and an object; the third is the blood on a portrait, which is a
// picture clipped to the creature's disc and faded out toward its middle.
const SHAPE_DISC = 0;
const SHAPE_RECT = 1;
const SHAPE_STAIN = 2;

// STAIN_ALPHA is how much of the portrait the blood is allowed to take. Low
// enough that the picture underneath is still what identifies the creature --
// two goblins that look MORE alike when they are hurt would be a worse table,
// not a bloodier one.
const STAIN_ALPHA = 0.62;

// BLOOD_INNER is how far in from the rim the stain reaches before it has faded
// to nothing, as a fraction of the radius. It is the whole reason this works: a
// splatter is dense in the middle, which is exactly where a face is, so the part
// that would cover it is thrown away and what survives is the arms and the
// droplets round the edge.
const BLOOD_INNER = 0.25;

// PULSE_REACH is how far in from the rim the heartbeat's glow reaches, as a
// fraction of the radius. Short, because the fall-off is the whole shape: a glow
// that got most of the way to the middle would be the token changing colour
// rather than a creature having a pulse.
const PULSE_REACH = 0.24;

// SPRITE_EDGE is the sprite layer's size. It is written here rather than
// imported so this module's arithmetic does not depend on how the cache was
// built; a test pins the two together.
const SPRITE_EDGE = 256;

const vertexSource = `#version 300 es
#define BORDER_PIXELS ${BORDER_PIXELS}.0

layout(location = 0) in vec2 a_corner;
layout(location = 1) in vec4 a_rect;
layout(location = 2) in vec4 a_border;
layout(location = 3) in vec4 a_style;
layout(location = 4) in vec4 a_fit;
layout(location = 5) in vec4 a_spin;

uniform mat3 u_clip;
uniform float u_scale;

out vec2 v_local;
flat out vec4 v_border;
flat out vec4 v_style;
flat out vec4 v_fit;
flat out vec2 v_wound;
flat out float v_edge;

void main() {
	v_local = a_corner * 2.0 - 1.0;
	v_border = a_border;
	v_style = a_style;
	v_fit = a_fit;
	v_wound = a_spin.zw;

	// The border is a device-pixel width turned into local units, which is why
	// it is computed here and not in the fragment shader: the half extent is a
	// per-instance value and this is the last place it is one.
	v_edge = BORDER_PIXELS / max(a_rect.z * u_scale, 1e-4);

	vec2 offset = v_local * a_rect.zw;
	vec2 turned = vec2(
		offset.x * a_spin.x - offset.y * a_spin.y,
		offset.x * a_spin.y + offset.y * a_spin.x
	);

	vec2 world = a_rect.xy + turned;
	gl_Position = vec4((u_clip * vec3(world, 1.0)).xy, 0.0, 1.0);
}
`;

const fragmentSource = `#version 300 es
precision highp float;
precision highp sampler2DArray;

in vec2 v_local;
flat in vec4 v_border;
flat in vec4 v_style;
flat in vec4 v_fit;
flat in vec2 v_wound;
flat in float v_edge;

uniform sampler2DArray u_sprites;

// u_pulse is how hard the heart is beating right now at each of its two rates:
// the slow one a badly hurt creature has in x, the fast one a dying creature has
// in y. Nothing here is a position -- see wounds.ts -- so this is brightness and
// only brightness.
uniform vec2 u_pulse;

const vec3 LUMA = vec3(0.299, 0.587, 0.114);

// BLOOD is what soaks into the rim, PALLOR is the cold cast the colour drains
// toward, and PULSE is the heartbeat's glow. What a splatter over a portrait is
// tinted to is NOT here: it changes when the creature dies, so it arrives per
// instance instead.
const vec3 BLOOD = vec3(0.42, 0.03, 0.03);
const vec3 PALLOR = vec3(0.82, 0.88, 1.0);
const vec3 PULSE = vec3(1.0, 0.24, 0.2);

out vec4 outColor;

void main() {
	float layer = v_style.x;
	float shape = v_style.y;
	float alpha = v_style.z;
	float grey  = v_style.w;

	// The picture, fitted. v_fit.xy is how much of the quad the image covers on
	// each axis -- under one for a letterboxed object, over one for a cropped
	// creature -- and v_fit.zw is how much of the 256 square layer the image
	// actually occupies, which is short of 1 for anything that is not square.
	vec2 t = (v_local / v_fit.xy) * 0.5 + 0.5;

	vec4 picture = vec4(0.0);
	if (layer >= 0.0 && t.x >= 0.0 && t.y >= 0.0 && t.x <= 1.0 && t.y <= 1.0) {
		picture = texture(u_sprites, vec3(t * v_fit.zw, layer));
	}

	vec3 rgb;
	float cover;

	if (shape < 0.5) {
		float r = length(v_local);
		float aa = max(fwidth(r), 1e-5);

		cover = 1.0 - smoothstep(1.0 - aa, 1.0, r);
		if (cover <= 0.0) {
			discard;
		}

		// WHATEVER THE PICTURE DOES NOT COVER IS THE KIND'S COLOUR, so a token
		// saved with a transparent background reads as a pawn rather than as a
		// hole in the table with a ring round it.
		rgb = mix(v_border.rgb, picture.rgb, picture.a);

		float border = smoothstep(1.0 - v_edge - aa, 1.0 - v_edge, r);
		rgb = mix(rgb, v_border.rgb, border * v_border.a);

		float wounded = v_wound.x;
		if (wounded > 0.0) {
			// BLOOD SOAKING IN FROM THE RIM, POOLED TOWARD THE BOTTOM. The
			// gravity term is what stops this reading as a ring somebody
			// blurred: +y is down on screen, because the clip matrix flips it.
			// THE REACH AND THE STRENGTH ARE SEPARATE. Scaling both by the same
			// number made the first band -- the one that has to be noticed at
			// all, because it is the first -- a thin darkening at the very edge
			// that read as a shadow. So a wound reaches a good way in from the
			// start and gets DEEPER rather than wider on the way down.
			float low = 0.55 + 0.45 * v_local.y;
			float rim = smoothstep(1.0 - (0.3 + 0.35 * wounded), 1.0, r) * low;
			rgb = mix(rgb, BLOOD, clamp(rim, 0.0, 1.0) * wounded);

			// AND THE COLOUR GOING OUT OF IT, toward a COLD grey rather than a
			// neutral one. Neutral is spoken for twice on this same axis --
			// 0.7 for a pawn players cannot see, 1.0 for a corpse -- and a
			// third meaning there would be three states that look alike.
			rgb = mix(rgb, PALLOR * dot(rgb, LUMA), 0.35 * wounded);
		}

		// THE PULSE, WHICH IS A GRADIENT ON THE INSIDE OF THE RIM AND DOES NOT
		// MOVE. Bright at the creature's edge, falling off quickly inward, and
		// the only thing that changes is how hard it is lit -- so the shape
		// stays out of the middle of the portrait, where the face is, and the
		// eye reads a beat rather than something crossing the token.
		float beating = v_wound.y;
		if (beating > 0.5) {
			float amount = beating < 1.5 ? u_pulse.x : u_pulse.y;
			rgb = mix(rgb, PULSE, smoothstep(1.0 - ${PULSE_REACH}, 1.0, r) * amount);
		}
	} else if (shape < 1.5) {
		cover = picture.a;
		if (cover <= 0.0) {
			discard;
		}
		rgb = picture.rgb;
	} else {
		// THE BLOOD ON A PORTRAIT: a splatter clipped to the creature's disc and
		// faded out toward its middle, so it soaks in from the edges rather than
		// covering the face. What identifies a pawn is its picture, and an
		// effect that made two goblins look MORE alike when they were hurt would
		// be a worse table rather than a bloodier one.
		float r = length(v_local);
		float aa = max(fwidth(r), 1e-5);

		cover = picture.a
			* (1.0 - smoothstep(1.0 - aa, 1.0, r))
			* smoothstep(${BLOOD_INNER}, 1.0, r);
		if (cover <= 0.0) {
			discard;
		}

		// THE TINT RIDES IN ON v_border, which a stain has no other use for. It
		// is arterial red on the living and the floor's own dried maroon on a
		// corpse; see BLOOD_DRIED in wounds.ts.
		rgb = v_border.rgb * picture.r;
	}

	// Desaturation is the GM's marker for a pawn players cannot see, and the
	// whole of what a dead creature is drawn as under its skull. A CORPSE KEEPS
	// ITS BLOOD RED while the body under it goes grey -- the stain is pushed
	// with no grey of its own -- and a pawn nobody can see has even that
	// desaturated with the rest of it.
	rgb = mix(rgb, vec3(dot(rgb, LUMA)), grey);

	outColor = vec4(rgb, cover * alpha);
}
`;

const names = ["u_clip", "u_sprites", "u_scale", "u_pulse"] as const;

// Drawn is one pawn as this pass needs it. It is deliberately NOT room.Pawn:
// the stress test's five hundred synthetic pawns are not in the store and never
// go near it, and a pass that took the protocol's type would have to be handed
// five hundred forged ones.
export interface Drawn {
	id: string;
	kind: Pawn["kind"];
	name: string;
	image: string;
	x: number;
	y: number;
	z: number;
	size: Pawn["size"];

	// width and height are an OBJECT'S size, in map pixels, and are zero for a
	// creature -- whose size comes from its category instead. See pawnExtents.
	width: number;
	height: number;

	// rotation is degrees clockwise about the centre, and is an object's alone.
	rotation: number;

	// hidden is the GM's copy of a pawn players cannot see. It is never true on
	// a player's, because they are never sent one.
	hidden: boolean;

	// health is the band the viewer was told this creature is in, and null when
	// they were told nothing about it at all -- neither a number nor a band --
	// which is the honest answer for a table whose labels are off. "dead" is
	// what draws the skull here; the rest of the scale is read by the wound ring
	// and the blood, neither of which is this pass's business. See wounds.ts.
	health: HPBand | null;
}

// PawnPulse is how hard the heart is beating right now, at each of its two
// rates, read once per frame and handed to every instance at once. See the note
// at the top of this file for why it is a uniform rather than a per-instance
// value.
export interface PawnPulse {
	slow: number;
	heart: number;
}

export interface PawnPass {
	// build rebuilds the instance buffer. It is called when the table changes
	// rather than every frame; see the note at the top of this file.
	//
	// alpha multiplies every instance, which is the whole of what makes a
	// second pass a GHOST pass: the same pawns, the same pictures, the same
	// arithmetic, drawn at half.
	build(pawns: readonly Drawn[], grid: Grid, sprites: SpriteCache, alpha?: number): void;

	draw(cam: Camera, deviceWidth: number, deviceHeight: number, dpr: number, pulse?: PawnPulse): void;

	// beating says whether anything in the buffer has a pulse, which is the
	// frame loop's question: a table with a creature dying on it animates, and
	// one without goes quiet. It is answered from the last build rather than
	// per frame because whether a creature beats changes only when its hit
	// points do -- and that is a rebuild.
	beating(): boolean;

	dispose(): void;
}

export function createPawnPass(gl: WebGL2RenderingContext): PawnPass {
	const program = createProgram(gl, vertexSource, fragmentSource);
	const at = uniforms(gl, program, names);

	const vao = gl.createVertexArray();
	gl.bindVertexArray(vao);

	const corners = gl.createBuffer();
	gl.bindBuffer(gl.ARRAY_BUFFER, corners);
	gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([0, 0, 1, 0, 0, 1, 1, 1]), gl.STATIC_DRAW);
	gl.enableVertexAttribArray(0);
	gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);

	const instances = gl.createBuffer();
	gl.bindBuffer(gl.ARRAY_BUFFER, instances);
	const stride = FLOATS_PER_INSTANCE * 4;
	for (let i = 0; i < 4; i++) {
		gl.enableVertexAttribArray(1 + i);
		gl.vertexAttribPointer(1 + i, 4, gl.FLOAT, false, stride, i * 16);
		gl.vertexAttribDivisor(1 + i, 1);
	}

	gl.enableVertexAttribArray(5);
	gl.vertexAttribPointer(5, 4, gl.FLOAT, false, stride, 64);
	gl.vertexAttribDivisor(5, 1);

	gl.bindVertexArray(null);
	gl.bindBuffer(gl.ARRAY_BUFFER, null);

	// Grown by doubling and never shrunk, which is the second performance rule:
	// a typed array reallocated per rebuild is a garbage collection pause on
	// every drag, and pauses are the jank that gets worse the longer a session
	// runs.
	let data = new Float32Array(64 * FLOATS_PER_INSTANCE);
	let count = 0;
	let texture: WebGLTexture | null = null;
	let pulsing = false;

	// order is the draw order, reused so a rebuild allocates nothing.
	let order: number[] = [];

	const matrix = new Float32Array(9);

	function reserve(needed: number): void {
		const floats = needed * FLOATS_PER_INSTANCE;
		if (floats <= data.length) {
			return;
		}

		let size = data.length;
		while (size < floats) {
			size *= 2;
		}
		data = new Float32Array(size);
	}

	function push(
		x: number, y: number, halfW: number, halfH: number,
		border: readonly [number, number, number], borderAlpha: number,
		layer: number, shape: number, alpha: number, grey: number,
		kx: number, ky: number, uvW: number, uvH: number,
		cos: number, sin: number, wounded: number, beat: number,
	): void {
		const at = count * FLOATS_PER_INSTANCE;

		data[at] = x;
		data[at + 1] = y;
		data[at + 2] = halfW;
		data[at + 3] = halfH;

		data[at + 4] = border[0];
		data[at + 5] = border[1];
		data[at + 6] = border[2];
		data[at + 7] = borderAlpha;

		data[at + 8] = layer;
		data[at + 9] = shape;
		data[at + 10] = alpha;
		data[at + 11] = grey;

		data[at + 12] = kx;
		data[at + 13] = ky;
		data[at + 14] = uvW;
		data[at + 15] = uvH;

		data[at + 16] = cos;
		data[at + 17] = sin;
		data[at + 18] = wounded;
		data[at + 19] = beat;

		count++;
	}

	return {
		build(pawns, grid, sprites, alpha = 1) {
			count = 0;
			pulsing = false;
			texture = sprites.texture();

			// Three instances each at worst: the pawn, the blood on a badly
			// wounded one, and the skull over a dead one.
			reserve(pawns.length * 3);

			// SORTED BY compareStack, which puts every object under every
			// creature and then orders within a kind by z and by id. It is the
			// same comparison the hit test uses, so what a click picks is what
			// is drawn on top of the pile. See scene.ts.
			if (order.length !== pawns.length) {
				order = pawns.map((_, i) => i);
			} else {
				for (let i = 0; i < pawns.length; i++) {
					order[i] = i;
				}
			}
			order.sort((a, b) => compareStack(pawns[a], pawns[b]));

			for (const index of order) {
				const pawn = pawns[index];
				const [halfW, halfH] = pawnExtents(pawn, grid.cellSize);
				const object = pawn.kind === "object";

				const dead = pawn.health === "dead";
				const opacity = alpha * (pawn.hidden ? HIDDEN_ALPHA : 1);
				const grey = pawn.hidden ? HIDDEN_GREY : dead ? 1 : 0;

				// A WOUND IS A CREATURE'S ALONE. A wagon and a door have hit
				// points and can be broken apart, and there is no blood in
				// either of them.
				const wounded = object ? 0 : hurt(pawn.health);
				const beat = object ? BEAT_NONE : beats(pawn.health);
				if (beat !== BEAT_NONE) {
					pulsing = true;
				}

				// The picture, or the initials that stand in for it -- both
				// while one is loading and for a pawn that has none at all.
				//
				// ASKING FOR IT IS ALSO WHAT KEEPS IT. sprite() marks the layer
				// used, which is what the cache's eviction skips, so a rebuild
				// is a rebuild AND a refresh of the whole working set. That is
				// why a picture arriving forces one: without it the set would go
				// stale between rebuilds, and with it eviction can only ever
				// reach a picture nothing on this floor is drawn from.
				const slot = sprites.sprite(pawn.image, 0) ?? sprites.initials(pawn.kind, pawn.name);
				const layer = slot ? slot.layer : -1;
				const [kx, ky] = slot
					? fitFactors(slot.w, slot.h, halfW, halfH, !object)
					: [1, 1];

				const angle = radians(pawn.rotation);
				const cos = pawn.rotation === 0 ? 1 : Math.cos(angle);
				const sin = pawn.rotation === 0 ? 0 : Math.sin(angle);

				push(
					pawn.x, pawn.y, halfW, halfH,
					KIND_COLORS[pawn.kind] ?? KIND_COLORS.npc,
					object ? 0 : 1,
					layer, object ? SHAPE_RECT : SHAPE_DISC, opacity, grey,
					kx, ky,
					slot ? slot.w / SPRITE_EDGE : 1,
					slot ? slot.h / SPRITE_EDGE : 1,
					cos, sin, wounded, beat,
				);

				// THE BLOOD ON THE PORTRAIT, which is a second instance for the
				// skull's reason: one instance samples one layer, and this is a
				// different picture over the same disc. Which splatter and how
				// far it is turned are both hashed off the pawn's own id, so
				// every creature wears its own wounds and wears the same ones on
				// everybody's screen.
				if (!object && bleeds(pawn.health)) {
					const mark = seed(pawn.id);
					const stain = sprites.sprite(bloodSprite(mark), 1);
					if (stain) {
						const turn = radians(mark % 360);
						const [bx, by] = fitFactors(stain.w, stain.h, halfW, halfH, true);

						// A CORPSE KEEPS ITS BLOOD, DRIED, and keeps it in
						// colour -- no grey of its own -- while the body under it
						// goes black and white. A pawn nobody can see has even
						// this desaturated, because that marker is about whether
						// the thing is on the table at all rather than about what
						// has happened to it.
						push(
							pawn.x, pawn.y, halfW, halfH,
							dead ? BLOOD_DRIED : BLOOD_FRESH, 0,
							stain.layer, SHAPE_STAIN, opacity * STAIN_ALPHA,
							pawn.hidden ? HIDDEN_GREY : 0,
							bx, by, stain.w / SPRITE_EDGE, stain.h / SPRITE_EDGE,
							Math.cos(turn), Math.sin(turn), 0, BEAT_NONE,
						);
					}
				}

				if (dead && !object) {
					const skull = sprites.glyph(SKULL);
					if (skull) {
						const size = halfW * SKULL_SCALE;
						const [sx, sy] = fitFactors(skull.w, skull.h, size, size, false);

						// UPRIGHT WHATEVER THE PAWN IS DOING. A skull is a
						// marker read by a person rather than part of the
						// picture, and a creature carries no rotation anyway.
						push(
							pawn.x, pawn.y, size, size,
							KIND_COLORS[pawn.kind] ?? KIND_COLORS.npc, 0,
							skull.layer, SHAPE_RECT, opacity, 0,
							sx, sy, skull.w / SPRITE_EDGE, skull.h / SPRITE_EDGE,
							1, 0, 0, BEAT_NONE,
						);
					}
				}
			}
		},

		beating: () => pulsing,

		draw(cam, deviceWidth, deviceHeight, dpr, pulse) {
			if (count === 0 || !texture) {
				return;
			}

			gl.useProgram(program);
			gl.bindVertexArray(vao);
			gl.bindBuffer(gl.ARRAY_BUFFER, instances);
			gl.bufferData(gl.ARRAY_BUFFER, data.subarray(0, count * FLOATS_PER_INSTANCE), gl.DYNAMIC_DRAW);

			gl.activeTexture(gl.TEXTURE0);
			gl.bindTexture(gl.TEXTURE_2D_ARRAY, texture);
			gl.uniform1i(at.u_sprites, 0);
			gl.uniform1f(at.u_scale, cam.zoom * dpr);
			gl.uniform2f(at.u_pulse, pulse?.slow ?? 0, pulse?.heart ?? 0);
			gl.uniformMatrix3fv(at.u_clip, false, clipMatrix(cam, deviceWidth, deviceHeight, dpr, matrix));

			gl.enable(gl.BLEND);
			gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
			gl.drawArraysInstanced(gl.TRIANGLE_STRIP, 0, 4, count);
			gl.disable(gl.BLEND);

			gl.bindVertexArray(null);
			gl.bindBuffer(gl.ARRAY_BUFFER, null);
		},

		dispose() {
			gl.deleteProgram(program);
			gl.deleteVertexArray(vao);
			gl.deleteBuffer(corners);
			gl.deleteBuffer(instances);
		},
	};
}

// fitFactors is how much of the quad the picture covers on each axis.
//
// ONE EXPRESSION FOR BOTH FITS, and the only difference is min or max. Contain
// shrinks the image until it is inside the quad, which letterboxes it; cover
// grows it until the quad is inside the image, which crops it. Contain is an
// object -- a wagon must be its own shape on the floor -- and cover is a
// creature, whose disc must not have bars in it.
//
// A factor over one means the image runs off the edge of the quad and the
// fragments past it are simply not drawn; a factor under one means the quad has
// nothing in it out there, which is the letterbox.
export function fitFactors(
	spriteW: number,
	spriteH: number,
	halfW: number,
	halfH: number,
	cover: boolean,
): [number, number] {
	if (spriteW <= 0 || spriteH <= 0 || halfW <= 0 || halfH <= 0) {
		return [1, 1];
	}

	const image = spriteW / spriteH;
	const quad = halfW / halfH;
	const pick = cover ? Math.max : Math.min;

	return [pick(1, image / quad), pick(1, quad / image)];
}
